CODON_TABLE_STRING = "FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
s = ""
d = {}  
d['U'] = 0
d['C'] = 1
d['A'] = 2
d['G'] = 3
f = open('output.OUT', 'w')
n = len(s)
def num(AminA):
    #print(AminA[0:3])
    return d[AminA[0]]*16 + d[AminA[1]]*4 + d[AminA[2]]
    
for i in range (0,n,3):
    z = num(s[i:i+3])
    c = CODON_TABLE_STRING[z]
    if c == '*': break
    f.write(c)
